package com.noop.mgecg;

// FILE VERSION 0.52.1 (11 Nov 2026): signal data for the direct phone-audio Lab runs (SimDirect). Excerpts of open-access PhysioNet databases (physionet.org), stored as delta-coded
// little-endian 16-bit values, deflated, Base64. Sources and units are given with each item. Research use; the excerpts are short and attributed here and in the decode log (addendum 155).

final class SimData {
    private SimData() {}

    /** average beat of MIT-BIH Arrhythmia Database record 103 (MLII), 142 normal beats, 500 Hz, -0.30 to +0.55 s around the R apex, R = 1 mV; unit 0.1 uV (425 values). */
    static final int TEMPLATE_N = 425;
    static final String[] TEMPLATE = {
        "",
    };
    /** Noise Stress Test Database record ma (muscle artefact), channel 1, first 100 s, resampled to 250 Hz; unit 0.2 uV (25000 values). */
    static final int MA_N = 25000;
    static final String[] MA = {
        "",
    };
    /** Noise Stress Test Database record em (electrode motion), channel 1, first 60 s, resampled to 125 Hz; unit 0.2 uV (7500 values). */
    static final int EM_N = 7500;
    static final String[] EM = {
        "",
    };
    /** MIT-BIH Atrial Fibrillation Database record 04746, signal ECG1, 250 Hz, seconds 15004 to 15124 (inside the AFIB annotation 10434-22784 s); unit 1 adu = 5 uV (30000 values). */
    static final int AF_N = 30000;
    static final String[] AF = {
        "",
    };

    /** Decodes one item to its 16-bit values. */
    static short[] decode(String[] parts, int n) {
        try {
            StringBuilder sb = new StringBuilder(); for (String p : parts) sb.append(p);
            byte[] z = java.util.Base64.getDecoder().decode(sb.toString()); java.util.zip.Inflater inf = new java.util.zip.Inflater(); inf.setInput(z);
            byte[] raw = new byte[n * 2]; int got = 0; while (got < raw.length && !inf.finished()) { int r = inf.inflate(raw, got, raw.length - got); if (r == 0 && (inf.needsInput() || inf.needsDictionary())) break; got += r; } inf.end();
            short[] out = new short[n]; int acc = 0; for (int i = 0; i < n; i++) { int d = (short) ((raw[2 * i] & 0xFF) | (raw[2 * i + 1] << 8)); acc += d; out[i] = (short) acc; }
            return out;
        } catch (Throwable t) { return new short[n]; }
    }
}
